"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["91840"],{56245(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.termo_exigido_formulario.versao_nao_encontrada","status":422,"titulo":"A vers\xe3o n\xe3o existe no cat\xe1logo de termos ou pertence a outro termo"},"descricao":{"codigo":"uniplus.selecao.termo_exigido_formulario.versao_nao_encontrada","requisitos":["UNI-REQ-0086"],"oQueAconteceu":["Os termos que um formul\xe1rio exige s\xe3o escolhidos num cat\xe1logo de termos, por termo e por vers\xe3o: o\\nprocesso n\xe3o digita o texto do termo, e congela a vers\xe3o escolhida (texto, base legal, forma de aceite e\\nresumo da vers\xe3o) com o processo. Um termo da lista enviada indica um par `termoId` e `versaoId` que o\\ncat\xe1logo n\xe3o tem: ou a vers\xe3o n\xe3o existe, ou ela existe, mas pertence a outro termo.","A resposta traz o erro no campo `termos[i].versaoId`, em `errors[]`, e acumula com as demais viola\xe7\xf5es\\ndos termos. A confer\xeancia vem depois da de forma de cada termo\\n([`obrigatoriedade_invalida`](/erros/uniplus.selecao.termo_exigido_formulario.obrigatoriedade_invalida)):\\num termo com viola\xe7\xe3o de forma n\xe3o chega a ser conferido contra o cat\xe1logo. Nada foi alterado."],"comoResolver":["Escolha, para cada termo, uma vers\xe3o que o cat\xe1logo de termos oferece para esse termo, e informe o\\n`termoId` e o `versaoId` do mesmo registro. Depois, envie os termos de novo. Se a vers\xe3o que se\\nqueria usar ainda n\xe3o foi cadastrada, o cadastro \xe9 feito por quem mant\xe9m o cat\xe1logo de termos."],"ondeAparece":["Grava\xe7\xe3o dos termos do formul\xe1rio"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Termo exigido formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);